begin;
insert into auth.users(id,raw_user_meta_data) values('ef810000-0000-4000-8000-000000000001','{}'),('ef810000-0000-4000-8000-000000000002','{}');
alter table public.profiles disable trigger guard_profile_privileges;
update public.profiles set role='OWNER',is_active=true where id='ef810000-0000-4000-8000-000000000001';
update public.profiles set role='STAFF',is_active=true where id='ef810000-0000-4000-8000-000000000002';
alter table public.profiles enable trigger guard_profile_privileges;
insert into public.coa_accounts(code,name,type,normal_balance) values('3101','Owner equity','EKUITAS','K') on conflict(code) do nothing;
create function pg_temp.assert_true(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'ASSERTION FAILED: %',label;end if;end$$;
create function pg_temp.expect_error(statement text,fragment text) returns void language plpgsql as $$begin begin execute statement;raise exception 'Expected failure';exception when others then if position(fragment in sqlerrm)=0 then raise;end if;end;end$$;
create function pg_temp.fail_opening_line() returns trigger language plpgsql as $$begin if current_setting('vetos.test.fail_opening',true)='1' and new.credit>0 then raise exception 'INJECTED_OPENING_FAILURE';end if;return new;end$$;
create trigger opening_test_failure before insert on public.journal_lines for each row execute function pg_temp.fail_opening_line();
update public.accounting_locks set closed_until=null where id;
create temp table opening_input(rows jsonb);
insert into opening_input values('[{"code":"1101","nilai":100,"sisi":"D"}]');
create temp table opening_result(result jsonb);
grant all on opening_input,opening_result to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','ef810000-0000-4000-8000-000000000001',true);
insert into opening_result select public.mutate_opening_balance('opening-create',null,'save',current_date-1,(select rows from opening_input),null);
select pg_temp.assert_true(public.mutate_opening_balance('opening-create',null,'save',current_date-1,(select rows from opening_input),null)=(select result from opening_result),'retry returns original opening');
select pg_temp.expect_error($q$select public.mutate_opening_balance('stale',null,'save',current_date-1,(select rows from opening_input),null)$q$,'sudah berubah');
select pg_temp.expect_error($q$select public.mutate_opening_balance('bad-account',(select (result->>'entry_id')::uuid from opening_result),'save',current_date-1,'[{"code":"4101","nilai":500,"sisi":"D"}]','Invalid account')$q$,'Akun saldo awal');
select pg_temp.expect_error($q$select public.mutate_opening_balance('fraction',(select (result->>'entry_id')::uuid from opening_result),'save',current_date-1,'[{"code":"1101","nilai":100.25,"sisi":"D"}]','Invalid amount')$q$,'rupiah bulat');
select set_config('vetos.test.fail_opening','1',true);
select pg_temp.expect_error($q$select public.mutate_opening_balance('rollback',(select (result->>'entry_id')::uuid from opening_result),'save',current_date-1,(select rows from opening_input),'Rollback test')$q$,'INJECTED_OPENING_FAILURE');
select set_config('vetos.test.fail_opening','0',true);
select pg_temp.assert_true((select count(*)=1 from public.journal_entries),'failed correction preserves only original header');
select pg_temp.assert_true((select count(*)=2 from public.journal_lines),'failed correction preserves original lines');
select pg_temp.assert_true((select opening_retired_at is null from public.journal_entries),'failed correction does not retire old balance');
update opening_input set rows='[{"code":"1101","nilai":200,"sisi":"D"}]';
update opening_result set result=public.mutate_opening_balance('opening-edit',(result->>'entry_id')::uuid,'save',current_date-1,(select rows from opening_input),'Koreksi saldo');
select pg_temp.assert_true((select count(*)=3 from public.journal_entries),'original, reversal and replacement retained');
select pg_temp.assert_true((select sum(debit-credit)=200 from public.journal_lines where account_id=(select id from public.coa_accounts where code='1101')),'replacement posts full new balance, not delta');
select pg_temp.assert_true((select count(*)=1 from public.journal_entries where source='saldo-awal' and opening_retired_at is null),'one active opening');
select pg_temp.expect_error($q$update public.journal_entries set deskripsi='Forged' where source='saldo-awal'$q$,'jalur resmi');
reset role;
update public.accounting_locks set closed_until=current_date-1 where id;
set local role authenticated;
select pg_temp.expect_error($q$select public.mutate_opening_balance('closed-source',(select (result->>'entry_id')::uuid from opening_result),'void',null,'[]','Closed source')$q$,'ditutup');
reset role;
update public.accounting_locks set closed_until=current_date-2 where id;
set local role authenticated;
select pg_temp.expect_error($q$select public.mutate_opening_balance('closed-target',(select (result->>'entry_id')::uuid from opening_result),'save',current_date-2,(select rows from opening_input),'Closed target')$q$,'ditutup');
select set_config('request.jwt.claim.sub','ef810000-0000-4000-8000-000000000002',true);
select pg_temp.expect_error($q$select public.mutate_opening_balance('staff',null,'save',current_date,(select rows from opening_input),null)$q$,'Akses saldo awal');
select set_config('request.jwt.claim.sub','ef810000-0000-4000-8000-000000000001',true);
select public.mutate_opening_balance('opening-void',(select (result->>'entry_id')::uuid from opening_result),'void',null,'[]','Batal simulasi');
select public.mutate_opening_balance('opening-void',(select (result->>'entry_id')::uuid from opening_result),'void',null,'[]','Batal simulasi');
select pg_temp.assert_true(not exists(select 1 from public.journal_entries where source='saldo-awal' and opening_retired_at is null),'void retires active opening without deletion');
select pg_temp.assert_true(not exists(select account_id from public.journal_lines group by account_id having sum(debit-credit)<>0),'void neutralizes balance');
select pg_temp.assert_true(public.get_opening_balance_result('opening-void')->>'entry_id' is not null,'void result recoverable without active balance');
reset role;
select pg_temp.assert_true((select count(*)=3 from public.opening_balance_requests),'failures leave no orphan request');
select pg_temp.assert_true((select count(*)=3 from public.opening_balance_revisions),'all successful operations audited once');
create temp table future_opening(id uuid);
grant select on future_opening to authenticated;
with inserted as(insert into public.journal_entries(no_jurnal,tanggal,source,source_ref) values('OPENING-FUTURE',current_date+1,'saldo-awal','future-fixture') returning id) insert into future_opening select id from inserted;
insert into public.journal_lines(entry_id,account_id,debit,credit)
 select (select id from future_opening),id,100,0 from public.coa_accounts where code='1101'
 union all select (select id from future_opening),id,0,100 from public.coa_accounts where code='3101';
set local role authenticated;
select pg_temp.expect_error($q$select public.mutate_opening_balance('future-source-save',(select id from future_opening),'save',current_date,(select rows from opening_input),'Future source')$q$,'Tanggal saldo awal sumber');
select pg_temp.expect_error($q$select public.mutate_opening_balance('future-source-void',(select id from future_opening),'void',null,'[]','Future source')$q$,'Tanggal saldo awal sumber');
reset role;
delete from public.journal_entries where id=(select id from future_opening);
alter table public.profiles disable trigger guard_profile_privileges;
update public.profiles set role='FINANCE' where id='ef810000-0000-4000-8000-000000000002';
alter table public.profiles enable trigger guard_profile_privileges;
set local role authenticated;
select set_config('request.jwt.claim.sub','ef810000-0000-4000-8000-000000000002',true);
select public.mutate_opening_balance('finance-create',null,'save',current_date,(select rows from opening_input),null);
select pg_temp.assert_true(public.get_opening_balance_result('finance-create')->>'entry_id' is not null,'finance initial save recovery does not require edit rights');
select pg_temp.expect_error($q$select public.mutate_opening_balance('finance-edit',(select id from public.journal_entries where source='saldo-awal' and opening_retired_at is null),'save',current_date,(select rows from opening_input),'Unauthorized edit')$q$,'Akses saldo awal');
reset role;
insert into public.role_modules(role,module_id) values('FINANCE','pengaturan');
set local role authenticated;
select pg_temp.expect_error($q$select public.mutate_opening_balance('finance-create',null,'save',current_date,(select rows from opening_input),null)$q$,'Buku Besar');
select pg_temp.expect_error($q$select public.get_opening_balance_result('finance-create')$q$,'Buku Besar');
reset role;
delete from public.role_modules where role='FINANCE';
insert into public.role_capabilities(role,all_branches) values('FINANCE',false);
set local role authenticated;
select pg_temp.expect_error($q$select public.mutate_opening_balance('finance-create',null,'save',current_date,(select rows from opening_input),null)$q$,'Akses saldo awal');
reset role;
select set_config('request.jwt.claim.sub','ef810000-0000-4000-8000-000000000001',true);
update public.profiles set is_active=false where id='ef810000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.expect_error($q$select public.mutate_opening_balance('opening-create',null,'save',current_date-1,'[{"code":"1101","nilai":100,"sisi":"D"}]',null)$q$,'Akses saldo awal');
rollback;
